#![recursion_limit = "256"]
mod app;
mod auth;
// Debug builds only: release builds (production) do not contain it.
#[cfg(debug_assertions)]
mod dev_oidc;
mod domain;
mod einro;
// Generated by `spacetime generate` / `task stdb:generate` — do not edit by hand.
mod module_bindings;
mod stdb;
mod ui;

fn main() {
	// Before the runtime starts, so no other thread reads the environment
	// while it is being set.
	#[cfg(debug_assertions)]
	load_dotenv();
	serve();
}

#[tokio::main]
async fn serve() {
	// Before the router: building it runs OIDC discovery, which in local dev
	// is against this provider.
	#[cfg(debug_assertions)]
	dev_oidc::start().await.expect("dev-oidc");

	topcoat::start(app::router().await).await.unwrap();
}

/// Load `.env` (if present) into the environment. Variables already set win,
/// so `PORT=… topcoat dev` still works. Debug builds only: production takes its
/// configuration from the real environment.
#[cfg(debug_assertions)]
fn load_dotenv() {
	match dotenvy::dotenv() {
		Ok(_) => {}
		Err(e) if e.not_found() => {}
		Err(e) => panic!(".env: {e}"),
	}
}
